    "code": "llm = LLM(model=\"Qwen/Qwen3-4B\", max_model_len=2560, gpu_memory_utilization=0.85)\nsp = SamplingParams(n=4, temperature=0.6, top_p=0.95, max_tokens=2048)\nouts = llm.chat(prompts, sp, chat_template_kwargs={\"enable_thinking\": True})"
